const std = @import("std");
const math = std.math;

pub const Error = error{
    EmptyInput,
    InvalidShape,
    InvalidAxis,
    OutOfBounds,
    ShapeMismatch,
    DivideByZero,
    InvalidConv2D,
    InvalidPads,
    InvalidReps,
    MustBeSquare,
    AllocationFailed,
};

pub const Fixed32_32 = struct {
    value: i64,
    const SCALING_FACTOR: f64 = 4294967296.0; // 2^32

    pub fn init(val: f32) Fixed32_32 {
        return fromFloat(val);
    }

    pub fn fromFloat(val: f32) Fixed32_32 {
        return .{ .value = @as(i64, @intFromFloat(val * @as(f32, @floatCast(SCALING_FACTOR)))) };
    }

    pub fn toFloat(self: Fixed32_32) f32 {
        return @as(f32, @floatFromInt(self.value)) / @as(f32, @floatCast(SCALING_FACTOR));
    }

    pub fn add(self: Fixed32_32, other: Fixed32_32) Fixed32_32 {
        return .{ .value = self.value + other.value };
    }

    pub fn sub(self: Fixed32_32, other: Fixed32_32) Fixed32_32 {
        return .{ .value = self.value - other.value };
    }

    pub fn mul(self: Fixed32_32, other: Fixed32_32) Fixed32_32 {
        const val = @as(i128, self.value) * @as(i128, other.value);
        return .{ .value = @as(i64, @truncate(val >> 32)) };
    }

    pub fn div(self: Fixed32_32, other: Fixed32_32) Fixed32_32 {
        const num = @as(i128, self.value) << 32;
        return .{ .value = @as(i64, @truncate(@divTrunc(num, @as(i128, other.value)))) };
    }
};

pub const FixedPoint16 = struct {
    value: i32,
    const SCALE: f32 = 65536.0;

    pub fn fromFloat(val: f32) FixedPoint16 {
        return .{ .value = @as(i32, @intFromFloat(val * SCALE)) };
    }
    pub fn toFloat(self: FixedPoint16) f32 {
        return @as(f32, @floatFromInt(self.value)) / SCALE;
    }
    pub fn add(self: FixedPoint16, other: FixedPoint16) FixedPoint16 {
        return .{ .value = self.value + other.value };
    }
    pub fn sub(self: FixedPoint16, other: FixedPoint16) FixedPoint16 {
        return .{ .value = self.value - other.value };
    }
    pub fn mul(self: FixedPoint16, other: FixedPoint16) FixedPoint16 {
        const v = @as(i64, self.value) * @as(i64, other.value);
        return .{ .value = @as(i32, @truncate(v >> 16)) };
    }
    pub fn div(self: FixedPoint16, other: FixedPoint16) FixedPoint16 {
        const n = @as(i64, self.value) << 16;
        return .{ .value = @as(i32, @truncate(@divTrunc(n, @as(i64, other.value)))) };
    }
};

pub const FixedPoint32 = Fixed32_32;

pub const PRNG = struct {
    state: u64,

    pub fn init(seed: u64) PRNG {
        return .{ .state = if (seed == 0) 0xCAFEBABE else seed };
    }

    pub fn next(self: *PRNG) u64 {
        var x = self.state;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.state = x;
        return x;
    }

    pub fn float(self: *PRNG) f32 {
        return @as(f32, @floatFromInt(self.next() % 1000000)) / 1000000.0;
    }
};

pub const DateTime = i64;
