pub const SpikingLiquidMachine = struct {
    layers: []LayerParams,
    config: CortexConfig,
    allocator: Allocator,

    pub fn init(allocator: Allocator, config: CortexConfig) !SpikingLiquidMachine {
        var layers = try allocator.alloc(LayerParams, config.num_layers);
        for (layers) |*layer| {
            layer.* = try LayerParams.init(allocator, config.num_neurons, config.num_neurons);
        }
        return .{ .layers = layers, .config = config, .allocator = allocator };
    }

    pub fn deinit(self: *SpikingLiquidMachine) void {
        for (self.layers) |*layer| {
            layer.deinit();
        }
        self.allocator.free(self.layers);
    }

    pub fn forward(self: *SpikingLiquidMachine, input: *const Tensor, dt: f32) !Tensor {
        var current_input = try input.copy(self.allocator);

        for (self.layers) |*layer| {
            var state = try NeuronState.init(self.allocator, self.config.num_neurons);
            defer state.deinit();

            // Calculate synaptic current: W * (input * cond) + b
            // Simplified: W * input + b (assuming input is pre-modulated or conductance is internal state)
            // Using conductance modulation from agi.txt logic: input * weights * conductance

            // 1. Modulate input with conductance (element-wise approximation for this step)
            // In full SLM, this is complex. We will do: (Weights @ Input) + Bias

            // Reshape input for matmul if needed [N] -> [N, 1]
            const in_shape = &.{ self.config.num_neurons, 1 };
            var input_col = try current_input.reshape(in_shape); // Error if shape mismatch, assuming valid input

            // W [N, N] @ I [N, 1] = [N, 1]
            // Actually input is [N], we treat it as column vector
            // We need to be careful with shapes. Let's assume input is [Batch, N] or just [N]. 
            // The logic in agi.txt assumes 1D input for simple update.

            // Perform synaptic integration
            // sums = Weights * input + biases
            // We need to manually implement the specific neuron update logic from C
            // because it's not a standard matmul.
            // "sums[i] += input[j] * weights[i][j] * init_cond[i]" -> Note init_cond[i] is post-synaptic? 
            // actually the C code says: `input[j] * weights[i][j] * init_cond[i]` where init_cond is `state->conductance`.

            // Let's implement the loop directly for correctness with the C source
            const N = self.config.num_neurons;

            // Access raw data for speed (unsafe but needed for the specific logic)
            const w_data = layer.weights.data;
            const b_data = layer.biases.data;
            const in_data = current_input.data;
            const pot_data = state.potential.data;
            const cond_data = state.conductance.data;
            const diff_data = state.diffusion.data;
            const res_data = state.resistance.data;
            const refr_data = state.refractory;

            var new_pot = try self.allocator.alloc(f32, N);
            defer self.allocator.free(new_pot);

            var spikes = try self.allocator.alloc(bool, N);
            defer self.allocator.free(spikes);

            // Neuron Update Step
            for (0..N) |i| {
                var sum: f32 = 0.0;
                // Dense matrix multiplication row
                const row_offset = i * N;
                for (0..N) |j| {
                    sum += in_data[j] * w_data[row_offset + j] * cond_data[i];
                }
                sum += b_data[i];

                if (pot_data[i] >= self.config.threshold) {
                    new_pot[i] = 0.0; // Reset
                    spikes[i] = true;
                } else if (refr_data[i] > 0) {
                    new_pot[i] = 0.0;
                    spikes[i] = false;
                } else {
                    const leak = pot_data[i] / self.config.time_constant * dt / cond_data[i] * res_data[i];
                    new_pot[i] = pot_data[i] + sum - leak;
                    spikes[i] = (new_pot[i] >= self.config.threshold);
                }
            }

            // State Update
            for (0..N) |i| {
                // Diffusion
                const spike_boost: f32 = if (spikes[i]) 0.1 * cond_data[i] else 0.0;
                diff_data[i] += self.config.diffusion_rate * spike_boost + new_pot[i] * dt * self.config.diffusion_rate;

                // Conductance
                if (spikes[i]) {
                    cond_data[i] = @min(cond_data[i] * 1.2, 2.0);
                }

                // Resistance (Memristor)
                res_data[i] = @exp(-new_pot[i]) * self.config.memristor_base;

                // Refractory
                if (spikes[i]) {
                    refr_data[i] = self.config.refractory_period;
                } else if (refr_data[i] > 0) {
                    refr_data[i] -= 1;
                }

                // Update Potential
                pot_data[i] = new_pot[i];
            }

            // Output generation for next layer
            // "current[i] = state.potential[i] / state.conductance[i] * state.mem_res[i] * SLM_SCALE;"
            const next_input = try self.allocator.alloc(f32, N);
            for (0..N) |i| {
                next_input[i] = pot_data[i] / cond_data[i] * res_data[i] * self.config.slm_scale;
            }

            // Swap current_input
            current_input.deinit();
            current_input = try Tensor.init(self.allocator, &.{N});
            @memcpy(current_input.data, next_input);
            self.allocator.free(next_input);
        }

        return current_input;
    }
};
