const std = @import("std");
const math = std.math;
const types = @import("types.zig");
const Tensor = @import("tensor.zig").Tensor;
const Allocator = std.mem.Allocator;
const PRNG = types.PRNG;

pub const CortexConfig = struct {
    num_neurons: usize = 18432,
    num_layers: usize = 12,
    time_constant: f32 = 0.1,
    diffusion_rate: f32 = 0.05,
    threshold: f32 = 1.0,
    refractory_period: i32 = 5,
    slm_scale: f32 = 0.0070422535,
    memristor_base: f32 = 1000.0,
};

pub const NeuronState = struct {
    potential: Tensor,
    conductance: Tensor,
    diffusion: Tensor,
    resistance: Tensor,
    refractory: []i32,
    allocator: Allocator,

    pub fn init(allocator: Allocator, num_neurons: usize) !NeuronState {
        var potential = try Tensor.init(allocator, &.{num_neurons});
        potential.fill(0.0);
        var conductance = try Tensor.init(allocator, &.{num_neurons});
        conductance.fill(1.0);
        var diffusion = try Tensor.init(allocator, &.{num_neurons});
        diffusion.fill(0.0);
        var resistance = try Tensor.init(allocator, &.{num_neurons});
        resistance.fill(1000.0);
        const refractory = try allocator.alloc(i32, num_neurons);
        @memset(refractory, 0);

        return .{
            .potential = potential,
            .conductance = conductance,
            .diffusion = diffusion,
            .resistance = resistance,
            .refractory = refractory,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *NeuronState) void {
        self.potential.deinit();
        self.conductance.deinit();
        self.diffusion.deinit();
        self.resistance.deinit();
        self.allocator.free(self.refractory);
    }
};

pub const LayerParams = struct {
    weights: Tensor,
    biases: Tensor,
    allocator: Allocator,

    pub fn init(allocator: Allocator, in_size: usize, out_size: usize) !LayerParams {
        const weights = try Tensor.randomNormal(allocator, &.{ out_size, in_size }, 0.0, 0.02, 42);
        const biases = try Tensor.init(allocator, &.{out_size});
        biases.fill(0.0);
        return .{ .weights = weights, .biases = biases, .allocator = allocator };
    }

    pub fn deinit(self: *LayerParams) void {
        self.weights.deinit();
        self.biases.deinit();
    }
};

pub const SpikingLiquidMachine = struct {
    layers: []LayerParams,
    config: CortexConfig,
    allocator: Allocator,

    pub fn init(allocator: Allocator, config: CortexConfig) !SpikingLiquidMachine {
        var layers = try allocator.alloc(LayerParams, config.num_layers);
        var i: usize = 0;
        while (i < config.num_layers) : (i += 1) {
            layers[i] = try LayerParams.init(allocator, config.num_neurons, config.num_neurons);
        }
        return .{ .layers = layers, .config = config, .allocator = allocator };
    }

    pub fn deinit(self: *SpikingLiquidMachine) void {
        var i: usize = 0;
        while (i < self.layers.len) : (i += 1) {
            self.layers[i].deinit();
        }
        self.allocator.free(self.layers);
    }

    pub fn forward(self: *SpikingLiquidMachine, input: *const Tensor, dt: f32) !Tensor {
        var current_input = try input.copy(self.allocator);
        var l: usize = 0;
        while (l < self.layers.len) : (l += 1) {
            var state = try NeuronState.init(self.allocator, self.config.num_neurons);
            defer state.deinit();

            const N = self.config.num_neurons;
            const w_data = self.layers[l].weights.data;
            const b_data = self.layers[l].biases.data;
            const in_data = current_input.data;
            const pot_data = state.potential.data;
            const cond_data = state.conductance.data;
            const diff_data = state.diffusion.data;
            const res_data = state.resistance.data;
            const refr_data = state.refractory;

            var new_pot = try self.allocator.alloc(f32, N);
            defer self.allocator.free(new_pot);

            var spikes = try self.allocator.alloc(bool, N);
            defer self.allocator.free(spikes);

            var i: usize = 0;
            while (i < N) : (i += 1) {
                var sum: f32 = 0.0;
                const row_offset = i * N;
                var j: usize = 0;
                while (j < N) : (j += 1) {
                    sum += in_data[j] * w_data[row_offset + j] * cond_data[i];
                }
                sum += b_data[i];

                if (pot_data[i] >= self.config.threshold) {
                    new_pot[i] = 0.0;
                    spikes[i] = true;
                } else if (refr_data[i] > 0) {
                    new_pot[i] = 0.0;
                    spikes[i] = false;
                } else {
                    const leak = pot_data[i] / self.config.time_constant * dt / cond_data[i] * res_data[i];
                    new_pot[i] = pot_data[i] + sum - leak;
                    if (new_pot[i] >= self.config.threshold) {
                        spikes[i] = true;
                    } else {
                        spikes[i] = false;
                    }
                }
            }

            i = 0;
            while (i < N) : (i += 1) {
                var spike_boost: f32 = 0.0;
                if (spikes[i]) {
                    spike_boost = 0.1 * cond_data[i];
                }
                diff_data[i] += self.config.diffusion_rate * spike_boost + new_pot[i] * dt * self.config.diffusion_rate;

                if (spikes[i]) {
                    cond_data[i] = cond_data[i] * 1.2;
                    if (cond_data[i] > 2.0) cond_data[i] = 2.0;
                }

                res_data[i] = @exp(-new_pot[i]) * self.config.memristor_base;

                if (spikes[i]) {
                    refr_data[i] = self.config.refractory_period;
                } else if (refr_data[i] > 0) {
                    refr_data[i] -= 1;
                }
                pot_data[i] = new_pot[i];
            }

            const next_input_data = try self.allocator.alloc(f32, N);
            i = 0;
            while (i < N) : (i += 1) {
                next_input_data[i] = pot_data[i] / cond_data[i] * res_data[i] * self.config.slm_scale;
            }

            current_input.deinit();
            current_input = try Tensor.init(self.allocator, &.{N});
            @memcpy(current_input.data, next_input_data);
            self.allocator.free(next_input_data);
        }
        return current_input;
    }
};
